@push('styles')
@include('public.business.admin.configurations._workspace_styles')
<style>
.workspace-layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:calc(100vh - 76px)}.auth-crud{margin-left:auto;margin-right:auto;max-width:1500px;padding:24px;min-width:0}.auth-crud h2{font-size:1.6rem;font-weight:750;margin:0 0 8px}.auth-help{opacity:.7;font-size:13px;margin-bottom:18px}.auth-panel{background:var(--card-bg,var(--surface,#fff));color:inherit;border:1px solid var(--border-color,rgba(125,125,125,.2));border-radius:14px;padding:18px;margin-bottom:18px}.auth-panel h3{margin:0 0 14px;font-size:17px}.auth-form{display:flex;align-items:end;flex-wrap:wrap;gap:10px}.auth-perm-form label{flex:1 1 180px}.auth-form label{font-size:12px;font-weight:650;display:flex;flex-direction:column;gap:5px}.auth-form input,.auth-form select{background:var(--input-bg,transparent);color:inherit;border:1px solid var(--border-color,rgba(125,125,125,.35));border-radius:9px;padding:10px;min-height:40px;min-width:120px;max-width:100%}.auth-form option{color:#111}.auth-wide{flex:1 1 300px!important}.auth-btn{display:inline-flex;align-items:center;justify-content:center;padding:9px 13px;border:1px solid var(--border-color,rgba(125,125,125,.25));border-radius:9px;background:var(--card-bg,transparent);color:inherit;cursor:pointer;font-size:12px;text-decoration:none}.auth-primary{background:#5146df;color:white;border-color:#5146df}.auth-danger{color:#db3b54}.auth-scroll{overflow-x:auto}.auth-table{width:100%;border-collapse:collapse;min-width:620px;font-size:13px}.auth-table th,.auth-table td{padding:12px;text-align:left;border-bottom:1px solid var(--border-color,rgba(125,125,125,.15));vertical-align:top}.auth-table th{font-size:11px;opacity:.7}.auth-table small{font-size:11px;opacity:.65}.auth-key{display:block;margin-top:4px;font-family:monospace}.auth-inline{display:inline-block;margin-left:5px}.auth-edit{margin-top:10px;padding:12px;border:1px solid var(--border-color,rgba(125,125,125,.2));border-radius:10px}.auth-pagination{margin-top:15px}.auth-ok,.auth-error{padding:12px;border-radius:10px;margin-bottom:13px;background:rgba(16,185,129,.12)}.auth-error{background:rgba(225,29,72,.1)}.auth-crud summary{display:inline-flex;list-style:none}.auth-crud details{display:inline-block;vertical-align:top}.auth-crud summary::-webkit-details-marker{display:none}@media(max-width:900px){.workspace-layout{grid-template-columns:minmax(0,1fr)}.workspace-sidebar{display:none}}@media(max-width:700px){.auth-crud{padding:12px}.auth-form>*{flex:1 1 100%}.auth-table{min-width:610px}}
[data-theme="dark"] .auth-panel{background:#1b2335;border-color:#334155}[data-theme="dark"] .auth-form input,[data-theme="dark"] .auth-form select{background:#12192a;color:#f8fafc;border-color:#475569}[data-theme="dark"] .auth-btn:not(.auth-primary){background:#1a2437}
</style>
@endpush
